int knapsack(int W, int wt[], int val[], int n) {
    vector<vector<int>> dp(n+1, vector<int>(W+1, 0));
    for(int i=1;i<=n;i++)
        for(int w=0;w<=W;w++) {
            dp[i][w] = dp[i-1][w];
            if(wt[i-1]<=w) dp[i][w]=max(dp[i][w], val[i-1]+dp[i-1][w-wt[i-1]]);
        }
    return dp[n][W];
}

