    int dp[n][n];
    memset(dp, 0, sizeof(dp));
    for(int L=2;L<n;L++)
        for(int i=1;i<n-L+1;i++) {
            int j=i+L-1; dp[i][j]=INT_MAX;
            for(int k=i;k<j;k++)
                dp[i][j]=min(dp[i][j], dp[i][k]+dp[k+1][j]+p[i-1]*p[k]*p[j]);
        }
    return dp[1][n-1];
}

