void floydWarshall(vector<vector<int>>& dist, int V) {
    int INF = 1e9;
    // Replace -1 with INF (except diagonal)
    for(int i=0;i<V;i++)
        for(int j=0;j<V;j++)
            if(i!=j && dist[i][j]==-1) dist[i][j]=INF;
    for(int k=0;k<V;k++)
        for(int i=0;i<V;i++)
            for(int j=0;j<V;j++)
                if(dist[i][k]!=INF && dist[k][j]!=INF)
                    dist[i][j]=min(dist[i][j], dist[i][k]+dist[k][j]);
    // Replace INF back with -1
    for(int i=0;i<V;i++)
        for(int j=0;j<V;j++)
            if(dist[i][j]>=INF) dist[i][j]=-1;
}

