def floyd_warshall(dist, V):
    INF = float('inf')
    for i in range(V):
        for j in range(V):
            if i != j and dist[i][j] == -1:
                dist[i][j] = INF
    for k in range(V):
        for i in range(V):
            for j in range(V):
                if dist[i][k] != INF and dist[k][j] != INF:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
    for i in range(V):
        for j in range(V):
            if dist[i][j] >= INF:
                dist[i][j] = -1

