int optimalBST(int freq[], int n) {
    int dp[n][n];
    for(int i=0;i<n;i++) dp[i][i]=freq[i];
    for(int L=2;L<=n;L++)
        for(int i=0;i<=n-L;i++) {
            int j=i+L-1;
            dp[i][j]=INT_MAX;
            int sum=0;
            for(int s=i;s<=j;s++) sum+=freq[s];
            for(int r=i;r<=j;r++) {
                int c=sum+(r>i?dp[i][r-1]:0)+(r<j?dp[r+1][j]:0);
                dp[i][j]=min(dp[i][j],c);
            }
        }
    return dp[0][n-1];
}

