def optimal_bst(freq, n):
    dp = [[0]*n for _ in range(n)]
    for i in range(n): dp[i][i] = freq[i]
    for L in range(2, n+1):
        for i in range(n-L+1):
            j = i+L-1
            dp[i][j] = float('inf')
            s = sum(freq[i:j+1])
            for r in range(i, j+1):
                c = s + (dp[i][r-1] if r>i else 0) + (dp[r+1][j] if r<j else 0)
                dp[i][j] = min(dp[i][j], c)
    return dp[0][n-1]

